            // TODO API_TEST_START
            java.io.File outFile = outputPath.resolve("out_toFiles.png").toFile();
            net.coobird.thumbnailator.Thumbnails.of(sourceImage)
                .forceSize(15, 15)
                .outputFormat("png")
                .toFiles(java.util.Arrays.asList(outFile));

